data.query:
query Query($where: MasterInventoryWhereInput, $orderBy: [MasterInventoryOrderByInput!], $first: Int, $after: String) {
  masterInventory(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        barcode
        inventory {
          edges {
            node {
              id
              number
              quantity {
                value
              }
              locationId
              location {
                id
                name
              }
              masterInventoryId
              productStrategyProcessId
              productStrategyProcess {
                id
                code
                productStrategy {
                  id
                  code
                  product {
                    id
                    code
                    name
                    number
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

query Query($where: InventoryWhereInput, $orderBy: [InventoryOrderByInput!], $first: Int, $after: String) {
  inventory(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        masterInventory {
          id

        }
        } 
    }
  }
}

query Query($where: ReceiptWhereInput, $orderBy: [ReceiptOrderByInput!], $first: Int, $after: String) {
  receipt(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        receiptLines {
          edges {
            node {
              inventories {
                edges {
                  node {
                    masterInventory {
                      id
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

